Run a code-review gate over the following pinned diff, headlessly and without tools. There is no database access — use the skill's review discipline, not its MCP plumbing. Emit: (1) a Findings section listing each issue with a severity tag, (2) a final `Verdict: pass|fail|uncertain` line with one-paragraph justification.

```diff
--- a/src/lib/retry.ts
+++ b/src/lib/retry.ts
@@ -1,3 +1,11 @@
-export async function withRetry<T>(fn: () => Promise<T>): Promise<T> {
-  return fn()
+export async function withRetry<T>(fn: () => Promise<T>, attempts = 3): Promise<T | null> {
+  for (let i = 0; i < attempts; i++) {
+    try {
+      return await fn()
+    } catch (e) {
+      // retry
+    }
+  }
+  return null
 }
```
